function applyTheme(value,restorePreset=true){const key=Object.hasOwn(themes,value)?value:'cyberpunk',theme=themes[key];document.body.dataset.theme=key;localStorage.setItem('tisma-theme',key);if(restorePreset){localStorage.setItem('tisma-wallpaper-mode','theme');document.body.classList.remove('has-custom-wallpaper');$('#custom-wallpaper-layer').classList.remove('visible');$('#custom-wallpaper-video').pause()}applyWallpaperAccent(!restorePreset&&localStorage.getItem('tisma-wallpaper-mode')==='custom'?undefined:null);if(ambientCanvas){resizeAmbientCanvas();syncAmbientBackground()}document.querySelectorAll('.theme-choice').forEach(button=>button.classList.toggle('active',button.dataset.theme===key));$('#feature-title-main').textContent=theme.title;$('#feature-title-sub').textContent=theme.subtitle;$('#feature-edition').textContent=theme.edition;$('#feature-description').textContent=theme.description;$('.hero-sigil').textContent=theme.sigil}
function applyWallpaperFit(value=localStorage.getItem('tisma-wallpaper-fit')||'cover'){const fit=['cover','contain','fill'].includes(value)?value:'cover';document.body.style.setProperty('--wallpaper-fit',fit);localStorage.setItem('tisma-wallpaper-fit',fit)}
function applyWallpaperAccent(value=localStorage.getItem('tisma-wallpaper-accent-value')){document.body.style.removeProperty('--accent');if(value&&localStorage.getItem('tisma-wallpaper-colors')!=='off')document.body.style.setProperty('--accent',value)}
function sampleWallpaperColor(media){try{const canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});canvas.width=32;canvas.height=32;context.drawImage(media,0,0,32,32);const pixels=context.getImageData(0,0,32,32).data,bins=Array(36).fill(0);for(let i=0;i<pixels.length;i+=4){const max=Math.max(pixels[i],pixels[i+1],pixels[i+2]),min=Math.min(pixels[i],pixels[i+1],pixels[i+2]),delta=max-min;if(max<55||max>245||delta<25)continue;let hue=0;if(max===pixels[i])hue=((pixels[i+1]-pixels[i+2])/delta)%6;else if(max===pixels[i+1])hue=(pixels[i+2]-pixels[i])/delta+2;else hue=(pixels[i]-pixels[i+1])/delta+4;hue=(Math.round(((hue*60+360)%360)/10)%36);bins[hue]+=delta}const hue=bins.indexOf(Math.max(...bins))*10,color='hsl('+hue+', 86%, 68%)';localStorage.setItem('tisma-wallpaper-accent-value',color);applyWallpaperAccent(color)}catch{}}
function wallpaperName(url){try{return decodeURIComponent(new URL(url).pathname.split('/').pop())}catch{return 'Fond personnel'}}
function setCustomWallpaper(url,name=''){const layer=$('#custom-wallpaper-layer'),image=$('#custom-wallpaper-image'),video=$('#custom-wallpaper-video');if(!url){layer.classList.remove('visible');document.body.classList.remove('has-custom-wallpaper');image.removeAttribute('src');video.pause();video.removeAttribute('src');localStorage.removeItem('tisma-custom-wallpaper');localStorage.removeItem('tisma-wallpaper-mode');localStorage.removeItem('tisma-wallpaper-accent-value');applyWallpaperAccent(null);$('#wallpaper-file-name').textContent='Fond du thème actuel';$('#clear-wallpaper-btn').classList.add('hidden');return}const extension=url.split(/[?#]/)[0].split('.').pop().toLowerCase(),isVideo=['mp4','webm'].includes(extension);image.style.display=isVideo?'none':'block';video.style.display=isVideo?'block':'none';if(isVideo){image.removeAttribute('src');video.src=url;video.load();video.addEventListener('loadeddata',()=>setTimeout(()=>sampleWallpaperColor(video),900),{once:true});if(!document.body.classList.contains('no-wallpaper'))video.play().catch(()=>toast('La vidéo du fond n’a pas pu démarrer automatiquement.'))}else{video.pause();video.removeAttribute('src');image.onload=()=>sampleWallpaperColor(image);image.onerror=()=>toast('Ce fichier image ne peut pas être affiché.');image.src=url}layer.classList.add('visible');document.body.classList.add('has-custom-wallpaper');localStorage.setItem('tisma-custom-wallpaper',url);localStorage.setItem('tisma-wallpaper-mode','custom');$('#wallpaper-file-name').textContent=name||wallpaperName(url);$('#clear-wallpaper-btn').classList.remove('hidden')}
