async function openSettings(){applyTheme(localStorage.getItem('tisma-theme')||'cyberpunk',false);applyProfileName(localStorage.getItem('tisma-profile-name')||'Tisma');$('#home-music-toggle').checked=localStorage.getItem('tisma-home-music')!=='off';$('#home-continue-toggle').checked=localStorage.getItem('tisma-home-continue')!=='off';$('#home-feature-toggle').checked=localStorage.getItem('tisma-home-feature')!=='off';$('#home-stats-toggle').checked=localStorage.getItem('tisma-home-stats')!=='off';renderHomeOrderControls();window.arcade.getAppVersion().then(version=>$('#app-version-label').textContent=version);$('#glow-toggle').checked=localStorage.getItem('tisma-glow')!=='off';$('#wallpaper-toggle').checked=localStorage.getItem('tisma-wallpaper')!=='off';$('#wallpaper-auto-color').checked=localStorage.getItem('tisma-wallpaper-colors')!=='off';$('#wallpaper-fit').value=localStorage.getItem('tisma-wallpaper-fit')||'cover';$('#settings-modal').classList.remove('hidden');try{collections=await window.arcade.getCollections();renderFilterOptions();const status=await window.arcade.getSteamCredentials();$('#steam-connection-status').textContent=status.configured?'Connecté · clé enregistrée localement':'Déconnecté';$('#steam-key-input').placeholder=status.configured?'Clé enregistrée · laisse vide pour conserver':'Clé API Web Steam (32 caractères)';$('#steam-key-input').value=''}catch(error){toast(error.message)}}
