function openModal(){$('#modal').classList.remove('hidden');$('#game-name').focus()}function closeModal(){$('#modal').classList.add('hidden')}async function autoCovers(force=false,quiet=true){if(!force&&!games.some(game=>!game.cover))return;try{const result=await window.arcade.fetchCovers(force);games=await window.arcade.getGames();render();if(result.count)toast('Jaquettes ajoutées automatiquement : '+result.count);else if(!quiet&&result.failed)toast('Connexion à Steam impossible. Vérifie Internet puis réessaie.');else if(!quiet&&result.attempted)toast('Aucune jaquette trouvée. Essaie un titre plus court ou choisis une image manuellement.')}catch(error){toast('La recherche de jaquettes a échoué. Vérifie ta connexion Internet.');console.warn(error)}}async function scan(quiet=false){const b=$('#scan-btn');b.disabled=true;b.innerHTML='<span>⟳</span> SCAN EN COURS…';try{const found=await window.arcade.scanGames(),before=games.length;for(const game of found)await window.arcade.addGame(game);games=await window.arcade.getGames();const n=Math.max(0,games.length-before);render();autoCovers();if(!quiet||n)toast(n?'Jeux ajoutés : '+n+' · '+[...new Set(found.map(g=>g.source))].join(', '):'Aucun nouveau jeu compatible détecté. Les doublons ont été ignorés.')}catch(e){toast("Le scan automatique a échoué : "+e.message)}finally{b.disabled=false;b.innerHTML='<span>⟳</span> SCANNER MON PC'}}
